/* Tech Robot · unitat 7 «Fins que…» (bucles amb condició) */
Object.assign(TBADGE, {
  u7fins: { id: 'u7fins', ico: '🏁', n: "Fins a la meta|Hasta la meta", d: "Has fet servir el bucle «Repeteix fins que…» per primera vegada.|Has usado el bucle «Repite hasta que…» por primera vez." },
  u7marea: { id: 'u7marea', ico: '🌊', n: "Domador/a de marees|Domador/a de mareas", d: "Els teus programes funcionen en camins de qualsevol llargada.|Tus programas funcionan en caminos de cualquier longitud." },
  u7cova: { id: 'u7cova', ico: '🔦', n: "Rescatador/a de la cova|Rescatador/a de la cueva", d: "Has acabat el projecte del rescat a la cova amb bucles amb condició.|Has terminado el proyecto del rescate en la cueva con bucles con condición." }
});
ROBOT_UNITS[7] = { t: "Fins que…|Hasta que…", d: "Bucles amb condició|Bucles con condición", color: '#F08A24', s: [
  /* ---------- Sessió 1 · Repeteix fins que arribis ---------- */
  { id: 'r7-1', t: "Repeteix fins que arribis|Repite hasta que llegues", min: 35, badge: 'u7fins',
    learn: ["«Repeteix fins que…» repeteix els blocs de dins fins que es compleix la condició, i llavors para.|«Repite hasta que…» repite los bloques de dentro hasta que se cumple la condición, y entonces para.",
      "Va bé quan no saps quantes vegades caldrà repetir: el bucle pregunta abans de cada volta.|Va bien cuando no sabes cuántas veces habrá que repetir: el bucle pregunta antes de cada vuelta.",
      "Si els blocs de dins no acosten en Bit a la condició, el bucle no s'acaba mai (bucle infinit).|Si los bloques de dentro no acercan a Bit a la condición, el bucle no se acaba nunca (bucle infinito)."],
    steps: [
      { k: 'quiz', ph: 'recorda', q: "Recordes el bucle? Amb <b>Repeteix 4 vegades: Endavant</b>, quantes caselles avança en Bit?|¿Recuerdas el bucle? Con <b>Repite 4 veces: Adelante</b>, ¿cuántas casillas avanza Bit?",
        opts: ["4 caselles|4 casillas", "1 casella|1 casilla", "5 caselles|5 casillas"], a: 0, ex: "El bucle repeteix els blocs de dins tantes vegades com diu el número.|El bucle repite los bloques de dentro tantas veces como dice el número." },
      { k: 'quiz', ph: 'recorda', q: "Quin bloc fa servir el sensor d'en Bit per mirar què té davant i decidir?|¿Qué bloque usa el sensor de Bit para mirar qué tiene delante y decidir?",
        opts: [tChip('if'), tChip('rep'), tChip('fwd')], a: 0, ex: "El «Si…» mira el món i decideix. Avui farem servir una pregunta com aquesta dins d'un bucle.|El «Si…» mira el mundo y decide. Hoy usaremos una pregunta como esta dentro de un bucle." },
      { k: 'story', ph: 'missio', who: 'both', scene: 'illa', title: "La cova de la muntanya|La cueva de la montaña",
        t: "Notícia a l'illa: dalt de la muntanya s'ha trobat una <b>cova</b>! En Bit s'apunta a l'expedició per explorar-la. Però avui hi ha <b>boira</b>, i ningú no veu quant de llarg és el camí fins al campament…|Noticia en la isla: ¡arriba de la montaña se ha encontrado una <b>cueva</b>! Bit se apunta a la expedición para explorarla. Pero hoy hay <b>niebla</b>, y nadie ve cuánto mide el camino hasta el campamento…" },
      { k: 'story', ph: 'missio', who: 'bit', mood: 'think', w: { map: ['.......', '>#####F', '.......'] },
        t: "BIP… Si no sé quantes caselles hi ha, quin número poso al «Repeteix»? Ja ho tinc: avançaré <b>fins que arribi</b>! Abans de cada pas miraré si ja hi soc.|BIP… Si no sé cuántas casillas hay, ¿qué número pongo en el «Repite»? Ya lo tengo: ¡avanzaré <b>hasta que llegue</b>! Antes de cada paso miraré si ya estoy." },
      { k: 'learn', ph: 'descobreix', cards: [
        { k: "Fins que…|Hasta que…", t: "Ho fas cada dia|Lo haces cada día", anim: 'u7eat',
          x: "Quan menges no comptes les cullerades: menges <b>fins que</b> el plat és buit. Quan vas a l'escola, camines <b>fins que</b> arribes al semàfor. Repetir una cosa fins que passa alguna cosa és un <span class='hl'>bucle amb condició</span>.|Cuando comes no cuentas las cucharadas: comes <b>hasta que</b> el plato está vacío. Cuando vas al cole, caminas <b>hasta que</b> llegas al semáforo. Repetir algo hasta que pasa algo es un <span class='hl'>bucle con condición</span>." },
        { k: "Per dins|Por dentro", t: "Primer pregunta, després repeteix|Primero pregunta, después repite", anim: 'u7check',
          x: "El bloc <b>Repeteix fins que…</b> fa una pregunta <b>abans de cada volta</b>: «ja hi he arribat?». Si la resposta és <b>no</b>, fa els blocs de dins i torna a preguntar. Si és <b>sí</b>, para i passa al bloc següent.|El bloque <b>Repite hasta que…</b> hace una pregunta <b>antes de cada vuelta</b>: «¿ya he llegado?». Si la respuesta es <b>no</b>, hace los bloques de dentro y vuelve a preguntar. Si es <b>sí</b>, para y pasa al bloque siguiente.",
          tip: "Aquesta pregunta es diu <span class='hl'>condició</span>. És com la del «Si…», però aquí es fa una vegada i una altra.|Esta pregunta se llama <span class='hl'>condición</span>. Es como la del «Si…», pero aquí se hace una y otra vez." },
        { k: "Bloc nou|Bloque nuevo", t: "Fins que arribis a la bandera|Hasta que llegues a la bandera", demo: { w: { map: ['......', '>####F', '......'] }, prog: TP('until:goal{ f }') },
          x: "Mira el programa: només té <b>dos blocs</b>, i en Bit arriba a la bandera sense que ningú hagi comptat les caselles. Si la bandera fos més lluny, el mateix programa també hi arribaria.|Mira el programa: solo tiene <b>dos bloques</b>, y Bit llega a la bandera sin que nadie haya contado las casillas. Si la bandera estuviera más lejos, el mismo programa también llegaría." },
        { k: "Una altra condició|Otra condición", t: "Fins que hi hagi un obstacle|Hasta que haya un obstáculo", demo: { w: { map: ['......', '>##*R.', '......'] }, prog: TP('until:wall{ f }') },
          x: "La condició pot ser una altra. Amb <b>fins que hi hagi un obstacle davant</b>, en Bit avança i <b>para just abans</b> de la roca, l'arbre o la vora del mapa. Aquí recull l'estrella del final del camí.|La condición puede ser otra. Con <b>hasta que haya un obstáculo delante</b>, Bit avanza y <b>para justo antes</b> de la roca, el árbol o el borde del mapa. Aquí recoge la estrella del final del camino.",
          tip: "Per canviar la condició d'un bucle, toca'l i tria <b>Canvia la condició</b>.|Para cambiar la condición de un bucle, tócalo y elige <b>Cambia la condición</b>." },
        { k: "Compte!|¡Cuidado!", t: "El bucle que no s'acaba mai|El bucle que no se acaba nunca", anim: 'u7inf',
          x: "Si els blocs de dins no acosten en Bit a la condició, la resposta sempre és «no» i el bucle <b>no s'acaba mai</b>. Això es diu <span class='hl'>bucle infinit</span>. En Bit s'atura sol quan veu que dona massa voltes, i llavors cal arreglar el programa.|Si los bloques de dentro no acercan a Bit a la condición, la respuesta siempre es «no» y el bucle <b>no se acaba nunca</b>. Esto se llama <span class='hl'>bucle infinito</span>. Bit se para solo cuando ve que da demasiadas vueltas, y entonces hay que arreglar el programa.",
          bad: "Repeteix fins que arribis a la bandera: Gira a la dreta.|Repite hasta que llegues a la bandera: Gira a la derecha.", good: "Repeteix fins que arribis a la bandera: Endavant.|Repite hasta que llegues a la bandera: Adelante." }
      ] },
      { k: 'quiz', ph: 'mans', q: "Quina d'aquestes frases és un <b>bucle amb condició</b>?|¿Cuál de estas frases es un <b>bucle con condición</b>?",
        opts: ["Bufa el globus fins que sigui ben gros|Sopla el globo hasta que esté bien grande", "Salta 3 vegades|Salta 3 veces", "Posa't la jaqueta|Ponte la chaqueta"], a: 0,
        ex: "Bufes, mires el globus i tornes a bufar… fins que és prou gros. No saps quantes bufades caldran!|Soplas, miras el globo y vuelves a soplar… hasta que es bastante grande. ¡No sabes cuántos soplidos harán falta!" },
      { k: 'unplug', ph: 'mans', ico: '🥄', title: "Fins que el plat sigui buit|Hasta que el plato esté vacío",
        t: "Necessites algú de casa, dos plats i un grapat de macarrons crus (o cigrons).|Necesitas a alguien de casa, dos platos y un puñado de macarrones crudos (o garbanzos).",
        steps: ["Poseu els macarrons en un plat. <b>No els compteu!</b>|Poned los macarrones en un plato. <b>¡No los contéis!</b>",
          "Una persona fa de robot. El programa és: <b>Repeteix fins que el plat sigui buit: passa un macarró a l'altre plat</b>.|Una persona hace de robot. El programa es: <b>Repite hasta que el plato esté vacío: pasa un macarrón al otro plato</b>.",
          "Abans de cada macarró, el robot pregunta en veu alta: «És buit?». Si no ho és, en passa un altre.|Antes de cada macarrón, el robot pregunta en voz alta: «¿Está vacío?». Si no lo está, pasa otro.",
          "Torneu-ho a fer amb més macarrons. Heu hagut de canviar el programa? No! Funciona amb qualsevol quantitat.|Volved a hacerlo con más macarrones. ¿Habéis tenido que cambiar el programa? ¡No! Funciona con cualquier cantidad."],
        tip: "Aquesta és la gràcia del «fins que»: el mateix programa serveix encara que no sàpigues quantes vegades caldrà repetir.|Esta es la gracia del «hasta que»: el mismo programa sirve aunque no sepas cuántas veces habrá que repetir." },
      { k: 'quiz', ph: 'prova', w: { map: ['.......', '>###F..', '.......'] }, q: "En Bit fa <b>Repeteix fins que arribis a la bandera: Endavant</b>. Si posem la bandera <b>dues caselles més lluny</b>, què cal canviar del programa?|Bit hace <b>Repite hasta que llegues a la bandera: Adelante</b>. Si ponemos la bandera <b>dos casillas más lejos</b>, ¿qué hay que cambiar del programa?",
        opts: ["Res: el programa ja funciona|Nada: el programa ya funciona", "Posar-hi dos Endavant més|Ponerle dos Adelante más", "Canviar la condició|Cambiar la condición"], a: 0,
        ex: "El bucle pregunta a cada pas si ja hi és. Si la bandera és més lluny, simplement fa més voltes.|El bucle pregunta en cada paso si ya está. Si la bandera está más lejos, simplemente da más vueltas." },
      { k: 'predict', ph: 'prova', q: "Aquest programa fa avançar en Bit <b>fins que hi hagi un obstacle davant</b>. <b>On acabarà?</b>|Este programa hace avanzar a Bit <b>hasta que haya un obstáculo delante</b>. <b>¿Dónde terminará?</b>",
        w: { map: ['..C...', '>#A#BR', '......'] }, prog: TP('until:wall{ f }'), a: 'B',
        ex: "No para a la A, perquè allà encara té camí lliure davant. Para a la B, just abans de la roca.|No para en la A, porque allí aún tiene camino libre delante. Para en la B, justo antes de la roca." },
      { k: 'spot', ph: 'investiga', q: "Aquest programa <b>no s'acaba mai</b>: en Bit dona voltes i més voltes. <b>Toca el bloc que s'ha de canviar.</b>|Este programa <b>no se acaba nunca</b>: Bit da vueltas y más vueltas. <b>Toca el bloque que hay que cambiar.</b>",
        w: { map: ['.....', '>###F', '.....'] }, prog: TPX('until:goal{ r! }'),
        ex: "Dins del bucle només hi ha «Gira a la dreta»: en Bit no s'acosta mai a la bandera. Hi havia d'anar «Endavant».|Dentro del bucle solo hay «Gira a la derecha»: Bit nunca se acerca a la bandera. Tenía que ir «Adelante»." },
      { k: 'move', ph: 'pausa', secs: 30, t: "Aixeca't! Fes girs de robot, un quart de volta cada vegada, <b>fins que</b> tornis a mirar la pantalla. Quants n'has fet? Ara camina al lloc <b>fins que</b> comptis fins a 10 en veu baixa.|¡Levántate! Haz giros de robot, un cuarto de vuelta cada vez, <b>hasta que</b> vuelvas a mirar la pantalla. ¿Cuántos has hecho? Ahora camina en el sitio <b>hasta que</b> cuentes hasta 10 en voz baja." },
      { k: 'build', ph: 'repte', q: "Estrena el bloc nou! Porta en Bit a la bandera amb <b>només 2 blocs</b>.|¡Estrena el bloque nuevo! Lleva a Bit a la bandera con <b>solo 2 bloques</b>.",
        w: { map: ['.......', '>#####F', '.......'] }, pal: ['fwd', 'until'], conds: ['goal'], max: 2, sol: TP('until:goal{ f }'),
        hint: "Posa primer el «Repeteix fins que…» i després un Endavant a dins.|Pon primero el «Repite hasta que…» y después un Adelante dentro." },
      { k: 'build', ph: 'repte', q: "Boira! A cada illa el camí fa una llargada diferent. Fes <b>un sol programa</b> que funcioni a les 3 illes.|¡Niebla! En cada isla el camino mide una longitud diferente. Haz <b>un solo programa</b> que funcione en las 3 islas.",
        w: { map: ['.......', '>##F...', '.......'], alts: [['.......', '>####F.', '.......'], ['.......', '>#####F', '.......']] }, pal: ['fwd', 'rep', 'until'], conds: ['goal'], sol: TP('until:goal{ f }'),
        hint: "Amb «Repeteix 3 vegades» només funciona a una illa. Quin bucle no necessita saber el número?|Con «Repite 3 veces» solo funciona en una isla. ¿Qué bucle no necesita saber el número?" },
      { k: 'build', ph: 'repte', q: "Recull l'estrella del final del camí. Aquí no hi ha bandera: fes que en Bit avanci <b>fins que hi hagi un obstacle davant</b>.|Recoge la estrella del final del camino. Aquí no hay bandera: haz que Bit avance <b>hasta que haya un obstáculo delante</b>.",
        w: { map: ['......', '>#*R..', '......'], alts: [['......', '>###*R', '......'], ['......', '>*R...', '......']] }, pal: ['fwd', 'until'], conds: ['goal', 'wall'], sol: TP('until:wall{ f }'),
        hint: "Toca el bloc «Repeteix fins que…» i tria «Canvia la condició» fins que digui «hi ha un obstacle davant».|Toca el bloque «Repite hasta que…» y elige «Cambia la condición» hasta que diga «hay un obstáculo delante»." },
      { k: 'build', ph: 'repte', q: "Ui, un bug! En Bit <b>es passa de la bandera</b>. La condició del bucle no és la bona: <b>arregla-la</b>.|¡Uy, un bug! Bit <b>se pasa de la bandera</b>. La condición del bucle no es la buena: <b>arréglala</b>.",
        w: { map: ['.......', '>##F##.', '.......'], alts: [['.......', '>####F#', '.......']] }, pal: ['fwd', 'until'], conds: ['wall', 'goal'], prog: TP('until:wall{ f }'), sol: TP('until:goal{ f }'),
        hint: "Ara en Bit para quan troba un obstacle. On ha de parar, de veritat?|Ahora Bit para cuando encuentra un obstáculo. ¿Dónde tiene que parar, de verdad?" },
      { k: 'build', ph: 'repte', q: "Una caixa per a l'expedició! Avança <b>fins que hi hagi una caixa</b>, agafa-la i porta-la a la casa del final del camí. Ha de funcionar a les 3 illes.|¡Una caja para la expedición! Avanza <b>hasta que haya una caja</b>, cógela y llévala a la casa del final del camino. Tiene que funcionar en las 3 islas.",
        w: { map: ['.......', '>#b###H', '.......'], alts: [['.......', '>###bH.', '.......'], ['.......', '>b##H..', '.......']] }, pal: ['fwd', 'pick', 'drop', 'until'], conds: ['box', 'wall'], sol: TP('until:box{ f } p until:wall{ f } d'),
        hint: "Són dos bucles seguits: un fins a la caixa i un altre fins al final del camí, on hi ha la casa.|Son dos bucles seguidos: uno hasta la caja y otro hasta el final del camino, donde está la casa." },
      { k: 'create', ph: 'crea', name: "El camí de la boira|El camino de la niebla",
        q: "Ara tu! Porta en Bit fins al campament (la bandera) fent servir <b>almenys 2 «Repeteix fins que…»</b>. Afegeix-hi els girs que calguin.|¡Ahora tú! Lleva a Bit hasta el campamento (la bandera) usando <b>al menos 2 «Repite hasta que…»</b>. Añade los giros que hagan falta.",
        crit: ["Arriba a la bandera|Llega a la bandera", "Fa servir almenys 2 «Repeteix fins que…»|Usa al menos 2 «Repite hasta que…»"],
        check: p => bitCountK(p, ['until']) >= 2 ? null : "Funciona, però fa servir menys de 2 «Repeteix fins que…». Prova de canviar els Endavant seguits per un bucle!|Funciona, pero usa menos de 2 «Repite hasta que…». ¡Prueba a cambiar los Adelante seguidos por un bucle!",
        w: { map: ['>###R.', '...#..', '...#..', '...##F'] }, pal: ['fwd', 'left', 'right', 'until'], conds: ['wall', 'goal'], sol: TP('until:wall{ f } r until:wall{ f } l until:goal{ f }') },
      { k: 'quiz', ph: 'tanca', q: "Quan para el bucle <b>Repeteix fins que arribis a la bandera</b>?|¿Cuándo para el bucle <b>Repite hasta que llegues a la bandera</b>?",
        opts: ["Quan en Bit és a la bandera|Cuando Bit está en la bandera", "Després de 5 voltes|Después de 5 vueltas", "No para mai|No para nunca"], a: 0 },
      { k: 'quiz', ph: 'tanca', q: "Un bucle no s'acaba mai. Què ha passat, segurament?|Un bucle no se acaba nunca. ¿Qué ha pasado, seguramente?",
        opts: ["Els blocs de dins no acosten en Bit a la condició|Los bloques de dentro no acercan a Bit a la condición", "En Bit s'ha cansat|Bit se ha cansado", "Hi ha massa blocs fora del bucle|Hay demasiados bloques fuera del bucle"], a: 0,
        ex: "Si en Bit no s'acosta mai a la bandera, la pregunta «hi he arribat?» sempre diu que no.|Si Bit nunca se acerca a la bandera, la pregunta «¿he llegado?» siempre dice que no." },
      { k: 'feel', ph: 'tanca' }
    ] },
  /* ---------- Sessió 2 · Camins de llargada desconeguda ---------- */
  { id: 'r7-2', t: "Camins de llargada desconeguda|Caminos de longitud desconocida", min: 35, badge: 'u7marea',
    learn: ["Amb «Repeteix fins que…», el mateix programa funciona en camins de llargades diferents.|Con «Repite hasta que…», el mismo programa funciona en caminos de longitudes diferentes.",
      "Si saps quantes vegades cal repetir, «Repeteix N vegades»; si no ho saps, «Repeteix fins que…».|Si sabes cuántas veces hay que repetir, «Repite N veces»; si no lo sabes, «Repite hasta que…».",
      "Per a un camí amb revolts: un bucle per a cada tros recte i el gir a fora, entre els bucles.|Para un camino con curvas: un bucle para cada trozo recto y el giro fuera, entre los bucles."],
    steps: [
      { k: 'quiz', ph: 'recorda', q: "Amb <b>Repeteix fins que hi hagi un obstacle davant: Endavant</b>, on para en Bit?|Con <b>Repite hasta que haya un obstáculo delante: Adelante</b>, ¿dónde para Bit?",
        opts: ["Just abans de l'obstacle|Justo antes del obstáculo", "A sobre de l'obstacle|Encima del obstáculo", "Al principi del camí|Al principio del camino"], a: 0,
        ex: "El bucle pregunta abans de cada pas. Quan té l'obstacle davant, ja no avança més.|El bucle pregunta antes de cada paso. Cuando tiene el obstáculo delante, ya no avanza más." },
      { k: 'quiz', ph: 'recorda', q: "Quin bloc faries servir si <b>no saps</b> quantes caselles hi ha fins a la bandera?|¿Qué bloque usarías si <b>no sabes</b> cuántas casillas hay hasta la bandera?",
        opts: [tChip('until'), tChip('rep')], a: 0, ex: "El «fins que» no necessita el número: para quan arriba.|El «hasta que» no necesita el número: para cuando llega." },
      { k: 'story', ph: 'missio', who: 'both', scene: 'moll', title: "Les marees del moll|Las mareas del muelle",
        t: "Ha arribat la barca amb l'equip de l'expedició: cordes, llanternes i cascos. En Bit l'ha de portar al campament. Però al moll hi ha <b>marea</b>: quan l'aigua puja o baixa, els camins es fan més llargs o més curts cada dia!|Ha llegado la barca con el equipo de la expedición: cuerdas, linternas y cascos. Bit tiene que llevarlo al campamento. Pero en el muelle hay <b>marea</b>: cuando el agua sube o baja, ¡los caminos se hacen más largos o más cortos cada día!" },
      { k: 'story', ph: 'missio', who: 'bit', mood: 'happy', t: "BIP! Necessito un programa que funcioni <b>avui, demà i demà passat</b>, sigui com sigui de llarg el camí. I compte, que els camins tenen revolts!|¡BIP! Necesito un programa que funcione <b>hoy, mañana y pasado mañana</b>, sea como sea de largo el camino. ¡Y cuidado, que los caminos tienen curvas!" },
      { k: 'learn', ph: 'descobreix', cards: [
        { k: "Programes per a tots els dies|Programas para todos los días", t: "Un programa, moltes illes|Un programa, muchas islas", anim: 'u7tide',
          x: "Quan el camí canvia de llargada, un programa amb el número exacte només funciona un dia. Amb <b>Repeteix fins que…</b>, el mateix programa funciona a totes les illes. A l'app ho veuràs amb les pestanyes <b>Illa 1 · Illa 2 · Illa 3</b>: el programa s'ha de provar a totes.|Cuando el camino cambia de longitud, un programa con el número exacto solo funciona un día. Con <b>Repite hasta que…</b>, el mismo programa funciona en todas las islas. En la app lo verás con las pestañas <b>Isla 1 · Isla 2 · Isla 3</b>: el programa se tiene que probar en todas." },
        { k: "Quin bucle?|¿Qué bucle?", t: "N vegades o fins que?|¿N veces o hasta que?", anim: 'u7vs',
          x: "Si <b>saps quantes vegades</b> cal repetir (pujar 5 graons, saltar 3 vegades), fes servir <b>Repeteix N vegades</b>. Si <b>no ho saps</b>, però saps quan has de parar (omplir el got fins que sigui ple), fes servir <b>Repeteix fins que…</b>.|Si <b>sabes cuántas veces</b> hay que repetir (subir 5 peldaños, saltar 3 veces), usa <b>Repite N veces</b>. Si <b>no lo sabes</b>, pero sabes cuándo tienes que parar (llenar el vaso hasta que esté lleno), usa <b>Repite hasta que…</b>." },
        { k: "Camins amb revolts|Caminos con curvas", t: "Fins a l'obstacle, gira i fins a la bandera|Hasta el obstáculo, gira y hasta la bandera", demo: { w: { map: ['>###.', '...#.', '...#.', '...F.'] }, prog: TP('until:wall{ f } r until:goal{ f }') },
          x: "Per a un camí en forma de L, posa un bucle per a cada tros recte i el gir entre els dos: <b>fins que hi hagi un obstacle</b> → <b>gira</b> → <b>fins que arribis</b>. Si els trossos fossin més llargs o més curts, el programa seria el mateix.|Para un camino en forma de L, pon un bucle para cada trozo recto y el giro entre los dos: <b>hasta que haya un obstáculo</b> → <b>gira</b> → <b>hasta que llegues</b>. Si los trozos fueran más largos o más cortos, el programa sería el mismo." },
        { k: "Compte!|¡Cuidado!", t: "El gir va fora del bucle|El giro va fuera del bucle", anim: 'u7inside',
          x: "Si poses el gir <b>dins</b> del «fins que», en Bit gira a cada pas i es fa un embolic. El gir s'ha de fer <b>una sola vegada</b>, quan el bucle ja ha acabat: per això va <b>després</b>, a fora.|Si pones el giro <b>dentro</b> del «hasta que», Bit gira en cada paso y se hace un lío. El giro se tiene que hacer <b>una sola vez</b>, cuando el bucle ya ha terminado: por eso va <b>después</b>, fuera.",
          bad: "Fins que hi hagi un obstacle: Endavant i Gira.|Hasta que haya un obstáculo: Adelante y Gira.", good: "Fins que hi hagi un obstacle: Endavant. I després, a fora: Gira.|Hasta que haya un obstáculo: Adelante. Y después, fuera: Gira." }
      ] },
      { k: 'quiz', ph: 'mans', q: "Has de pujar les <b>12 escales</b> de casa i ja saps que n'hi ha 12. Quin bucle va millor?|Tienes que subir las <b>12 escaleras</b> de casa y ya sabes que hay 12. ¿Qué bucle va mejor?",
        opts: ["«Repeteix 12 vegades»: ja sé el número|«Repite 12 veces»: ya sé el número", "«Repeteix fins que…»: no sé el número|«Repite hasta que…»: no sé el número"], a: 0, keep: true,
        ex: "Quan el número és conegut i no canvia, el bucle de N vegades és el més clar.|Cuando el número es conocido y no cambia, el bucle de N veces es el más claro." },
      { k: 'quiz', ph: 'mans', q: "Remenes la xocolata desfeta <b>fins que no hi queden grumolls</b>. Quin bucle és?|Remueves el chocolate deshecho <b>hasta que no quedan grumos</b>. ¿Qué bucle es?",
        opts: ["«Repeteix fins que…»|«Repite hasta que…»", "«Repeteix 10 vegades»|«Repite 10 veces»"], a: 0, keep: true,
        ex: "No saps quantes voltes caldran: mires la xocolata i pares quan està bé.|No sabes cuántas vueltas harán falta: miras el chocolate y paras cuando está bien." },
      { k: 'unplug', ph: 'mans', ico: '👣', title: "Passes de gegant, passes de formiga|Pasos de gigante, pasos de hormiga",
        t: "Amb algú de casa. Trieu un camí recte i sense obstacles: del sofà fins a la porta, per exemple.|Con alguien de casa. Elegid un camino recto y sin obstáculos: del sofá hasta la puerta, por ejemplo.",
        steps: ["El programa és: <b>Repeteix fins que toquis la porta: fes una passa</b>.|El programa es: <b>Repite hasta que toques la puerta: da un paso</b>.",
          "Primer feu-lo amb passes de gegant i compteu-les.|Primero hacedlo con pasos de gigante y contadlos.",
          "Després, amb passes de formiga (un peu just davant de l'altre). Quantes n'hi ha ara?|Después, con pasos de hormiga (un pie justo delante del otro). ¿Cuántos hay ahora?",
          "El número ha canviat, però el programa és el mateix!|¡El número ha cambiado, pero el programa es el mismo!"],
        tip: "Per això els robots fan servir el «fins que»: no cal saber el número abans de començar.|Por eso los robots usan el «hasta que»: no hace falta saber el número antes de empezar." },
      { k: 'parsons', ph: 'prova', q: "Ordena els blocs perquè en Bit segueixi el camí amb revolt fins a la bandera.|Ordena los bloques para que Bit siga el camino con curva hasta la bandera.",
        w: { map: ['....', '>##.', '..#.', '..F.'] }, pool: TP('until:wall{ f } r until:goal{ f }'), sol: TP('until:wall{ f } r until:goal{ f }'),
        hint: "Primer el tros recte fins a l'arbre, després el gir, i després el tros fins a la bandera.|Primero el trozo recto hasta el árbol, después el giro, y después el trozo hasta la bandera." },
      { k: 'predict', ph: 'prova', q: "Aquest programa té dos bucles i un gir. <b>On acabarà en Bit?</b>|Este programa tiene dos bucles y un giro. <b>¿Dónde terminará Bit?</b>",
        w: { map: ['>##A.', '.C.#.', '...B.', '.....'] }, prog: TP('until:wall{ f } r until:wall{ f }'), a: 'B',
        ex: "El primer bucle para a la A, davant de l'arbre. Després gira i el segon bucle baixa fins a la B.|El primer bucle para en la A, delante del árbol. Después gira y el segundo bucle baja hasta la B." },
      { k: 'spot', ph: 'investiga', q: "En Bit hauria de seguir el camí en L, però es fa un embolic. <b>Toca el bloc que està en mal lloc.</b>|Bit debería seguir el camino en L, pero se hace un lío. <b>Toca el bloque que está en mal lugar.</b>",
        w: { map: ['>##..', '..#..', '..#..', '..F..'] }, prog: TPX('until:wall{ f r! } until:goal{ f }'),
        ex: "El gir és dins del primer bucle: en Bit gira després de cada pas. Havia d'anar a fora, entre els dos bucles.|El giro está dentro del primer bucle: Bit gira después de cada paso. Tenía que ir fuera, entre los dos bucles." },
      { k: 'move', ph: 'pausa', secs: 30, t: "Posa't dret/a. Fes passes al lloc <b>fins que</b> comptis 5, gira a la dreta i fes passes <b>fins que</b> vegis una finestra. Després gira a l'esquerra i salta <b>fins que</b> comptis 8!|Ponte de pie. Da pasos en el sitio <b>hasta que</b> cuentes 5, gira a la derecha y da pasos <b>hasta que</b> veas una ventana. Después gira a la izquierda y ¡salta <b>hasta que</b> cuentes 8!" },
      { k: 'build', ph: 'repte', q: "Porta l'equip al campament! El camí té un revolt, i a cada illa els trams fan una llargada diferent.|¡Lleva el equipo al campamento! El camino tiene una curva, y en cada isla los tramos miden una longitud diferente.",
        w: { map: ['>##..', '..#..', '..F..', '.....'], alts: [['>####', '....#', '....#', '....F'], ['>#...', '.#...', '.#...', '.F...']] }, pal: ['fwd', 'left', 'right', 'rep', 'until'], conds: ['wall', 'goal'], sol: TP('until:wall{ f } r until:goal{ f }'),
        hint: "Un bucle per a cada tros recte, i el gir entre els dos.|Un bucle para cada trozo recto, y el giro entre los dos." },
      { k: 'build', ph: 'repte', q: "Aquí el primer tram <b>sempre fa 2 caselles</b>, però el segon canvia cada dia. Compte: el camí de dalt continua i no porta enlloc!|Aquí el primer tramo <b>siempre mide 2 casillas</b>, pero el segundo cambia cada día. Cuidado: ¡el camino de arriba continúa y no lleva a ningún sitio!",
        w: { map: ['>####.', '..#...', '..F...', '......', '......'], alts: [['>####.', '..#...', '..#...', '..#...', '..F...'], ['>####.', '..#...', '..#...', '..F...', '......']] }, pal: ['fwd', 'left', 'right', 'rep', 'until'], conds: ['wall', 'goal'], sol: TP('2{ f } r until:goal{ f }'),
        hint: "Per al tram que no canvia ja saps el número. Per al que canvia, fes servir «fins que».|Para el tramo que no cambia ya sabes el número. Para el que cambia, usa «hasta que»." },
      { k: 'build', ph: 'repte', q: "Un camí amb <b>dos revolts</b> fins a la bandera. Ho has de fer amb <b>6 blocs com a màxim</b>: busca el tros que es repeteix!|Un camino con <b>dos curvas</b> hasta la bandera. Lo tienes que hacer con <b>6 bloques como máximo</b>: ¡busca el trozo que se repite!",
        w: { map: ['>####.', '....#.', 'F####.', '......', '......'], alts: [['>##...', '..#...', '..#...', 'F##...', '......'], ['>#####', '.....#', '.....#', '.....#', '.F####']] }, pal: ['fwd', 'left', 'right', 'rep', 'until'], conds: ['wall', 'goal'], max: 6, sol: TP('2{ until:wall{ f } r } until:goal{ f }'),
        hint: "«Avança fins a l'obstacle i gira a la dreta» passa dues vegades. Posa-ho dins d'un «Repeteix 2 vegades».|«Avanza hasta el obstáculo y gira a la derecha» pasa dos veces. Ponlo dentro de un «Repite 2 veces»." },
      { k: 'build', ph: 'repte', q: "Ui! En aquest programa el gir s'ha ficat on no tocava. <b>Arregla'l</b> perquè funcioni a les dues illes.|¡Uy! En este programa el giro se ha metido donde no tocaba. <b>Arréglalo</b> para que funcione en las dos islas.",
        w: { map: ['>###.', '...#.', '...F.', '.....'], alts: [['>#...', '.#...', '.F...', '.....']] }, pal: ['fwd', 'left', 'right', 'until'], conds: ['wall', 'goal'], prog: TP('until:wall{ f r } until:goal{ f }'), sol: TP('until:wall{ f } r until:goal{ f }'),
        hint: "Toca el «Gira» de dins del bucle i esborra'l. Després posa'n un de nou entre els dos bucles.|Toca el «Gira» de dentro del bucle y bórralo. Después pon uno nuevo entre los dos bucles." },
      { k: 'build', ph: 'repte', q: "L'escala del penya-segat! Tots els graons són iguals, però cada illa en té un nombre diferent. Puja fins a la bandera.|¡La escalera del acantilado! Todos los peldaños son iguales, pero cada isla tiene un número diferente. Sube hasta la bandera.",
        w: { map: ['.....', '.....', '..F..', '.##..', '>#...'], alts: [['.....', '...F.', '..##.', '.##..', '>#...'], ['....F', '...##', '..##.', '.##..', '>#...']] }, pal: ['fwd', 'left', 'right', 'rep', 'until'], conds: ['goal', 'wall'], sol: TP('until:goal{ f l f r }'),
        hint: "Un graó és: Endavant, Gira a l'esquerra, Endavant, Gira a la dreta. Repeteix-lo fins que arribis.|Un peldaño es: Adelante, Gira a la izquierda, Adelante, Gira a la derecha. Repítelo hasta que llegues." },
      { k: 'create', ph: 'crea', name: "El viatge de la marea|El viaje de la marea",
        q: "Porta en Bit fins a la bandera. El camp és obert i pots triar el camí, però el programa ha de funcionar <b>a les dues illes</b>… i la bandera no és al mateix lloc!|Lleva a Bit hasta la bandera. El campo es abierto y puedes elegir el camino, pero el programa tiene que funcionar <b>en las dos islas</b>… ¡y la bandera no está en el mismo sitio!",
        crit: ["Funciona a les 2 illes|Funciona en las 2 islas", "Fa servir «Repeteix fins que…»|Usa «Repite hasta que…»"],
        check: p => bitCountK(p, ['until']) >= 1 ? null : "Funciona, però el repte demana fer servir un «Repeteix fins que…».|Funciona, pero el reto pide usar un «Repite hasta que…».",
        w: { map: ['>.....', '..R...', '......', '.R..R.', '.....F'], alts: [['>.....', '...R..', 'R.....', '.....F', '......']] }, pal: ['fwd', 'left', 'right', 'rep', 'until'], conds: ['wall', 'goal'], sol: TP('until:wall{ f } r until:goal{ f }') },
      { k: 'quiz', ph: 'tanca', q: "Per què un «fins que» serveix per a camins de llargades diferents?|¿Por qué un «hasta que» sirve para caminos de longitudes diferentes?",
        opts: ["Perquè para quan es compleix la condició, no després d'un número fix|Porque para cuando se cumple la condición, no después de un número fijo", "Perquè va més de pressa|Porque va más deprisa", "Perquè gira sol|Porque gira solo"], a: 0 },
      { k: 'quiz', ph: 'tanca', q: "Saps que has de saltar <b>exactament 3 vegades</b>. Quin bucle és més clar?|Sabes que tienes que saltar <b>exactamente 3 veces</b>. ¿Qué bucle es más claro?",
        opts: ["Repeteix 3 vegades|Repite 3 veces", "Repeteix fins que…|Repite hasta que…"], a: 0, keep: true,
        ex: "Si el número és conegut, el bucle de N vegades diu exactament el que vols.|Si el número es conocido, el bucle de N veces dice exactamente lo que quieres." },
      { k: 'feel', ph: 'tanca' }
    ] },
  /* ---------- Sessió 3 · Combinem-ho tot ---------- */
  { id: 'r7-3', t: "Combinem-ho tot|Combinémoslo todo", min: 35,
    learn: ["Un «Si… si no…» dins d'un «Repeteix fins que…» fa que en Bit decideixi a cada pas.|Un «Si… si no…» dentro de un «Repite hasta que…» hace que Bit decida en cada paso.",
      "Dins d'un bucle hi poden anar funcions, llums, notes i comptadors.|Dentro de un bucle pueden ir funciones, luces, notas y contadores.",
      "Els programes llargs es llegeixen bloc a bloc i es prediuen abans d'executar-los.|Los programas largos se leen bloque a bloque y se predicen antes de ejecutarlos."],
    steps: [
      { k: 'quiz', ph: 'recorda', q: "En un camí en forma de L, on va el gir: dins o fora del bucle?|En un camino en forma de L, ¿dónde va el giro: dentro o fuera del bucle?",
        opts: ["A fora, després del bucle|Fuera, después del bucle", "A dins del bucle|Dentro del bucle", "Abans de començar|Antes de empezar"], a: 0,
        ex: "El gir només s'ha de fer una vegada, quan el tros recte s'ha acabat.|El giro solo se tiene que hacer una vez, cuando el trozo recto se ha terminado." },
      { k: 'quiz', ph: 'recorda', q: "Recordes el «Si… si no…»? Amb <b>Si hi ha un obstacle davant: Gira. Si no: Endavant</b>, què fa en Bit si té el camí lliure?|¿Recuerdas el «Si… si no…»? Con <b>Si hay un obstáculo delante: Gira. Si no: Adelante</b>, ¿qué hace Bit si tiene el camino libre?",
        opts: ["Avança|Avanza", "Gira|Gira", "No fa res|No hace nada"], a: 0, ex: "Com que no hi ha obstacle, fa la part del «si no»: Endavant.|Como no hay obstáculo, hace la parte del «si no»: Adelante." },
      { k: 'story', ph: 'missio', who: 'both', scene: 'taller', title: "L'equip de la cova|El equipo de la cueva",
        t: "Al taller preparem en Bit per entrar a la cova. Allà dins els passadissos giren a cada moment i no tenim cap mapa. En Bit haurà de <b>decidir a cada pas</b>: si hi ha roca davant, girar; si no, avançar.|En el taller preparamos a Bit para entrar en la cueva. Allí dentro los pasillos giran a cada momento y no tenemos ningún mapa. Bit tendrá que <b>decidir en cada paso</b>: si hay roca delante, girar; si no, avanzar." },
      { k: 'story', ph: 'missio', who: 'bit', mood: 'happy', t: "BIP BIP! Avui ajuntarem <b>tot el que sé</b>: bucles, sensors, «si… si no…», funcions, llums i comptadors. Serà el meu programa més espavilat!|¡BIP BIP! Hoy juntaremos <b>todo lo que sé</b>: bucles, sensores, «si… si no…», funciones, luces y contadores. ¡Será mi programa más espabilado!" },
      { k: 'learn', ph: 'descobreix', cards: [
        { k: "Decidir a cada pas|Decidir en cada paso", t: "Un «si» dins d'un «fins que»|Un «si» dentro de un «hasta que»", anim: 'u7follow',
          x: "Si poses un <b>Si… si no…</b> dins d'un <b>Repeteix fins que arribis</b>, en Bit mira el camí a cada volta i decideix: si hi ha un obstacle, gira; si no, avança. Així segueix camins que <b>ningú no li ha explicat</b>.|Si pones un <b>Si… si no…</b> dentro de un <b>Repite hasta que llegues</b>, Bit mira el camino en cada vuelta y decide: si hay un obstáculo, gira; si no, avanza. Así sigue caminos que <b>nadie le ha explicado</b>." },
        { k: "En directe|En directo", t: "El camí que gira|El camino que gira", demo: { w: { map: ['>###.', '...#.', '.F.#.', '.###.'] }, prog: TP('until:goal{ if:wall{ r } else{ f } }') },
          x: "Fixa't en el bloc que s'il·lumina: quan hi ha un arbre davant, en Bit fa <b>Gira</b>; quan el camí és lliure, fa <b>Endavant</b>. Aquest programa de 4 blocs serveix per a un camí curt o per a un de molt llarg.|Fíjate en el bloque que se ilumina: cuando hay un árbol delante, Bit hace <b>Gira</b>; cuando el camino está libre, hace <b>Adelante</b>. Este programa de 4 bloques sirve para un camino corto o para uno muy largo." },
        { k: "Girs als dos costats|Giros a los dos lados", t: "Mira a l'esquerra i a la dreta|Mira a la izquierda y a la derecha", demo: { w: { map: ['>#...', '.#...', '.###.', '...#F'] }, prog: TP('until:goal{ if:freeL{ l } if:freeR{ r } f }') },
          x: "Si el camí gira cap als dos costats, en Bit fa servir els sensors dels costats: <b>si hi ha camí a l'esquerra</b>, gira a l'esquerra; <b>si hi ha camí a la dreta</b>, gira a la dreta. I després, un pas endavant.|Si el camino gira hacia los dos lados, Bit usa los sensores de los lados: <b>si hay camino a la izquierda</b>, gira a la izquierda; <b>si hay camino a la derecha</b>, gira a la derecha. Y después, un paso adelante." },
        { k: "Amb funcions|Con funciones", t: "Un bucle que crida una funció|Un bucle que llama a una función", demo: { w: { map: ['.....', '...F.', '..##.', '.##..', '>#...'] }, prog: TP('until:goal{ A }'), fns: { A: 'f l f r' }, fnName: { A: 'graó|peldaño' } },
          x: "Dins d'un bucle també hi pot anar una <b>funció</b>. Aquí la funció <b>graó</b> fa pujar un graó de l'escala, i el bucle la crida fins que en Bit arriba a dalt.|Dentro de un bucle también puede ir una <b>función</b>. Aquí la función <b>peldaño</b> hace subir un peldaño de la escalera, y el bucle la llama hasta que Bit llega arriba." },
        { k: "Compte!|¡Cuidado!", t: "Llegeix abans d'executar|Lee antes de ejecutar", demo: { w: { map: ['.......', '>*#*#*F', '.......'] }, prog: TP('until:goal{ f if:gem{ add:1 } }') },
          x: "Els programes llargs es llegeixen <b>a poc a poc</b>, bloc a bloc, amb el dit. Aquest compta les estrelles fins a la bandera: a cada volta avança i, <b>si</b> hi ha una estrella, suma 1 al comptador. Quantes en comptarà?|Los programas largos se leen <b>poco a poco</b>, bloque a bloque, con el dedo. Este cuenta las estrellas hasta la bandera: en cada vuelta avanza y, <b>si</b> hay una estrella, suma 1 al contador. ¿Cuántas contará?",
          bad: "Executar-lo de seguida i mirar què passa.|Ejecutarlo enseguida y mirar qué pasa.", good: "Predir què farà, executar-lo i comprovar-ho (amb «Pas a pas» si cal).|Predecir qué hará, ejecutarlo y comprobarlo (con «Paso a paso» si hace falta)." }
      ] },
      { k: 'seq', ph: 'mans', q: "Què fa en Bit a cada volta del programa <b>Fins que arribis: si hi ha obstacle, gira; si no, endavant</b>? Ordena-ho.|¿Qué hace Bit en cada vuelta del programa <b>Hasta que llegues: si hay obstáculo, gira; si no, adelante</b>? Ordénalo.",
        items: ["Pregunta: ja he arribat a la bandera?|Pregunta: ¿ya he llegado a la bandera?", "Si no hi és, mira: tinc un obstacle davant?|Si no está, mira: ¿tengo un obstáculo delante?", "Si n'hi ha, gira. Si no, avança.|Si lo hay, gira. Si no, avanza.", "Torna a començar la volta.|Vuelve a empezar la vuelta."],
        ex: "Primer la condició del bucle, després la del «si», i torna a començar. Així fins a la bandera.|Primero la condición del bucle, después la del «si», y vuelve a empezar. Así hasta la bandera." },
      { k: 'unplug', ph: 'mans', ico: '🧭', title: "El robot que decideix|El robot que decide",
        t: "Amb algú de casa, en un passadís o una habitació sense coses per terra.|Con alguien de casa, en un pasillo o una habitación sin cosas por el suelo.",
        steps: ["Trieu una meta: la porta de la cuina, per exemple.|Elegid una meta: la puerta de la cocina, por ejemplo.",
          "El robot segueix aquest programa: <b>Repeteix fins que arribis a la meta: si tens una paret o un moble davant, gira a la dreta; si no, fes una passa</b>.|El robot sigue este programa: <b>Repite hasta que llegues a la meta: si tienes una pared o un mueble delante, gira a la derecha; si no, da un paso</b>.",
          "Camineu a poc a poc i amb els ulls ben oberts!|¡Caminad despacio y con los ojos bien abiertos!",
          "Hi heu arribat? Si el robot dona voltes sense arribar mai, heu trobat un bucle infinit: canvieu la regla o la meta!|¿Habéis llegado? Si el robot da vueltas sin llegar nunca, habéis encontrado un bucle infinito: ¡cambiad la regla o la meta!"],
        tip: "Proveu-ho des de llocs diferents: de vegades la mateixa regla funciona i de vegades no. Els programadors i programadores de robots també ho han de provar molt!|Probadlo desde sitios diferentes: a veces la misma regla funciona y a veces no. ¡Los programadores y programadoras de robots también lo tienen que probar mucho!" },
      { k: 'predict', ph: 'prova', q: "Un programa llarg: llegeix-lo amb el dit, bloc a bloc. <b>On acabarà en Bit?</b>|Un programa largo: léelo con el dedo, bloque a bloque. <b>¿Dónde terminará Bit?</b>",
        w: { map: ['A##B.', '...#.', '...#.', '>##C.'] }, prog: TP('3{ until:wall{ f } l }'), a: 'A',
        ex: "Fa tres vegades «fins a l'obstacle i gira a l'esquerra»: primer fins a la C, després fins a la B i finalment fins a la A.|Hace tres veces «hasta el obstáculo y gira a la izquierda»: primero hasta la C, después hasta la B y finalmente hasta la A." },
      { k: 'spot', ph: 'investiga', q: "Aquest programa hauria de seguir el camí fins a la bandera, però en Bit gira cap al costat equivocat i no hi arriba mai. <b>Toca el bloc equivocat.</b>|Este programa debería seguir el camino hasta la bandera, pero Bit gira hacia el lado equivocado y no llega nunca. <b>Toca el bloque equivocado.</b>",
        w: { map: ['>###', '...#', 'F###'] }, prog: TPX('until:goal{ if:wall{ l! } else{ f } }'),
        ex: "Tots els revolts d'aquest camí giren cap a la dreta. Amb «Gira a l'esquerra», en Bit surt del camí bo.|Todas las curvas de este camino giran hacia la derecha. Con «Gira a la izquierda», Bit sale del camino bueno." },
      { k: 'move', ph: 'pausa', secs: 30, t: "Fes de robot que decideix: camina al lloc i, cada vegada que algú (o tu mateix/a) piqui de mans, <b>gira a la dreta</b>. Si no hi ha picada, <b>fes una passa</b>. Fins que comptis 20 passes!|Haz de robot que decide: camina en el sitio y, cada vez que alguien (o tú mismo/a) dé una palmada, <b>gira a la derecha</b>. Si no hay palmada, <b>da un paso</b>. ¡Hasta que cuentes 20 pasos!" },
      { k: 'build', ph: 'repte', q: "Entrem a la cova! Els passadissos giren sempre cap a la dreta, però cada illa és diferent. Fes un programa que funcioni a les 3.|¡Entramos en la cueva! Los pasillos giran siempre hacia la derecha, pero cada isla es diferente. Haz un programa que funcione en las 3.",
        w: { map: ['>####', '....#', '..F.#', '..###', '.....'], alts: [['>##..', '..#..', 'F##..', '.....', '.....'], ['>###.', '...#.', '...#.', '...#.', 'F###.']] }, pal: ['fwd', 'left', 'right', 'until', 'if', 'else'], conds: ['goal', 'wall'], sol: TP('until:goal{ if:wall{ r } else{ f } }'),
        hint: "Dins del «fins que arribis», posa un «Si hi ha un obstacle davant» amb «si no». Què ha de fer en Bit a cada part?|Dentro del «hasta que llegues», pon un «Si hay un obstáculo delante» con «si no». ¿Qué tiene que hacer Bit en cada parte?" },
      { k: 'build', ph: 'repte', q: "Ara els passadissos giren cap als dos costats! Fes servir els sensors de l'esquerra i de la dreta.|¡Ahora los pasillos giran hacia los dos lados! Usa los sensores de la izquierda y de la derecha.",
        w: { map: ['>#...', '.#...', '.###.', '...#.', '...#F'], alts: [['>##..', '..#..', '..#..', '.##..', '.F...'], ['>###.', '...#.', '.###.', '.#...', '.##F.']] }, pal: ['fwd', 'left', 'right', 'until', 'if'], conds: ['goal', 'freeL', 'freeR', 'wall'], sol: TP('until:goal{ if:freeL{ l } if:freeR{ r } f }'),
        hint: "A cada volta: si hi ha camí a l'esquerra, gira a l'esquerra; si n'hi ha a la dreta, gira a la dreta; i després, Endavant.|En cada vuelta: si hay camino a la izquierda, gira a la izquierda; si lo hay a la derecha, gira a la derecha; y después, Adelante." },
      { k: 'build', ph: 'repte', q: "Hi ha roques al passadís! La funció <b>esquiva</b> ja està feta: fa que en Bit doni la volta a una roca. Fes el programa principal: avança fins a la bandera i, si hi ha una roca davant, esquiva-la.|¡Hay rocas en el pasillo! La función <b>esquiva</b> ya está hecha: hace que Bit rodee una roca. Haz el programa principal: avanza hasta la bandera y, si hay una roca delante, esquívala.",
        w: { map: ['.......', '.###...', '>#R#F..'], alts: [['.......', '..###..', '>##R#F.'], ['.......', '.######', '>#R##RF']] }, pal: ['fwd', 'left', 'right', 'until', 'if', 'else', 'call'], conds: ['goal', 'wall'],
        fns: { A: TP('l f r f f r f l') }, fnName: { A: "esquiva|esquiva" }, sol: TP('until:goal{ if:wall{ A } else{ f } }'),
        hint: "És com seguir un camí que gira, però quan hi ha un obstacle, en lloc de «Gira» crida la funció.|Es como seguir un camino que gira, pero cuando hay un obstáculo, en lugar de «Gira» llama a la función." },
      { k: 'build', ph: 'repte', q: "Quantes estrelles hi ha a cada passadís? Fes que en Bit avanci fins a la bandera i, <b>si hi ha una estrella</b>, sumi 1 al comptador.|¿Cuántas estrellas hay en cada pasillo? Haz que Bit avance hasta la bandera y, <b>si hay una estrella</b>, sume 1 al contador.",
        w: { map: ['.......', '>#*##*F', '.......'], count: 2, vname: "comptador d'estrelles|contador de estrellas", alts: [{ map: ['.......', '>**#*#F', '.......'], count: 3 }, { map: ['.......', '>####*F', '.......'], count: 1 }] },
        pal: ['fwd', 'until', 'if', 'add'], conds: ['goal', 'gem'], sol: TP('until:goal{ f if:gem{ add:1 } }'),
        hint: "Dins del bucle: primer Endavant, i després «Si hi ha una estrella: Suma 1».|Dentro del bucle: primero Adelante, y después «Si hay una estrella: Suma 1»." },
      { k: 'build', ph: 'repte', q: "Senyals per a l'equip: en Bit ha d'encendre el <b>llum vermell a cada revolt</b> i el <b>verd quan arriba</b>. Però el programa té un bug. Fes-lo <b>pas a pas</b> i arregla'l.|Señales para el equipo: Bit tiene que encender la <b>luz roja en cada curva</b> y la <b>verde cuando llega</b>. Pero el programa tiene un bug. Hazlo <b>paso a paso</b> y arréglalo.",
        w: { map: ['>##..', '..#..', 'F##..', '.....'], lights: ['r', 'r', 'g'], alts: [{ map: ['>###.', '...#.', '...#.', '...F.'], lights: ['r', 'g'] }] },
        pal: ['fwd', 'left', 'right', 'until', 'if', 'else', 'light'], conds: ['goal', 'wall'], colors: ['r', 'g'],
        prog: TP('until:goal{ if:wall{ r } else{ f light:r } } light:g'), sol: TP('until:goal{ if:wall{ r light:r } else{ f } } light:g'),
        hint: "Ara el llum vermell s'encén a cada pas. On l'has de posar perquè només s'encengui quan en Bit gira?|Ahora la luz roja se enciende en cada paso. ¿Dónde la tienes que poner para que solo se encienda cuando Bit gira?" },
      { k: 'create', ph: 'crea', name: "La patrulla de la cova|La patrulla de la cueva",
        q: "Programa la patrulla: en Bit ha de recórrer els passadissos fins a la bandera i recollir les estrelles, i ha de funcionar <b>a les dues coves</b>. Si vols, afegeix-hi llums, notes o un comptador!|Programa la patrulla: Bit tiene que recorrer los pasillos hasta la bandera y recoger las estrellas, y tiene que funcionar <b>en las dos cuevas</b>. ¡Si quieres, añade luces, notas o un contador!",
        crit: ["Funciona a les 2 coves|Funciona en las 2 cuevas", "Fa servir «Repeteix fins que…» amb un «Si…» a dins|Usa «Repite hasta que…» con un «Si…» dentro", "Extra: llums, notes o comptador|Extra: luces, notas o contador"],
        check: p => bitCountK(p, ['until']) >= 1 && bitCountK(p, ['if']) >= 1 ? null : "Funciona! Però el repte demana un «Repeteix fins que…» amb un «Si…» a dins.|¡Funciona! Pero el reto pide un «Repite hasta que…» con un «Si…» dentro.",
        w: { map: ['>##*#.', '....#.', '.F..*.', '.####.', '......'], alts: [['>####*', '.....#', '.....#', 'F*####', '......']] },
        pal: ['fwd', 'left', 'right', 'until', 'if', 'else', 'light', 'note', 'add'], conds: ['goal', 'wall', 'gem', 'freeL', 'freeR'], colors: ['g', 'y', 'r', 'u'], notes: ['do', 'mi', 'sol'],
        sol: TP('until:goal{ if:wall{ r } else{ f } }') },
      { k: 'quiz', ph: 'tanca', q: "Quin programa fa que en Bit segueixi un camí que gira sempre a la dreta, sigui com sigui de llarg?|¿Qué programa hace que Bit siga un camino que gira siempre a la derecha, sea como sea de largo?",
        opts: ["Fins que arribis: si hi ha obstacle, gira a la dreta; si no, endavant|Hasta que llegues: si hay obstáculo, gira a la derecha; si no, adelante", "Repeteix 4 vegades: endavant|Repite 4 veces: adelante", "Si hi ha obstacle: gira a la dreta|Si hay obstáculo: gira a la derecha"], a: 0 },
      { k: 'quiz', ph: 'tanca', q: "Abans d'executar un programa llarg, què és millor fer?|Antes de ejecutar un programa largo, ¿qué es mejor hacer?",
        opts: ["Llegir-lo bloc a bloc i predir què farà|Leerlo bloque a bloque y predecir qué hará", "Executar-lo moltes vegades, a veure si surt|Ejecutarlo muchas veces, a ver si sale", "Esborrar-lo i fer-ne un de curt|Borrarlo y hacer uno corto"], a: 0 },
      { k: 'feel', ph: 'tanca' }
    ] },
  /* ---------- Sessió 4 · Projecte: rescat a la cova ---------- */
  { id: 'r7-4', t: "Projecte: rescat a la cova|Proyecto: rescate en la cueva", min: 40, proj: true, badge: 'u7cova',
    learn: ["Un projecte gran es fa a trossos: primer el pla, després els blocs, i es prova a cada cova.|Un proyecto grande se hace a trozos: primero el plan, después los bloques, y se prueba en cada cueva.",
      "Amb «Repeteix fins que…», el mateix programa de rescat serveix per a coves que canvien.|Con «Repite hasta que…», el mismo programa de rescate sirve para cuevas que cambian.",
      "Has acabat la unitat dels bucles amb condició!|¡Has terminado la unidad de los bucles con condición!"],
    steps: [
      { k: 'quiz', ph: 'recorda', q: "En Bit ha de seguir un camí que gira i no saps quant fa. Què poses dins del «Repeteix fins que arribis»?|Bit tiene que seguir un camino que gira y no sabes cuánto mide. ¿Qué pones dentro del «Repite hasta que llegues»?",
        opts: ["Un «Si hi ha un obstacle… si no…»|Un «Si hay un obstáculo… si no…»", "Només un «Gira a la dreta»|Solo un «Gira a la derecha»", "Res|Nada"], a: 0,
        ex: "Amb només «Gira», en Bit no avançaria i el bucle no s'acabaria mai.|Con solo «Gira», Bit no avanzaría y el bucle no se acabaría nunca." },
      { k: 'story', ph: 'missio', who: 'both', scene: 'illa', title: "Alerta al campament!|¡Alerta en el campamento!",
        t: "Alerta! Una ventada ha tancat el passadís gran de la cova, i <b>el material de l'expedició s'ha quedat a dins</b>: les caixes amb les eines i les estrelles de cristall que s'havien trobat. Tothom és al campament i està bé, però cal anar-ho a buscar!|¡Alerta! Una ventolera ha cerrado el pasillo grande de la cueva, y <b>el material de la expedición se ha quedado dentro</b>: las cajas con las herramientas y las estrellas de cristal que se habían encontrado. Todo el mundo está en el campamento y está bien, ¡pero hay que ir a buscarlo!" },
      { k: 'story', ph: 'missio', who: 'bit', mood: 'think', t: "BIP! La cova és estranya: <b>els passadissos canvien</b> cada vegada que hi entro. No puc comptar caselles… però sé fer servir el «fins que»! Aquest és el meu pla:|¡BIP! La cueva es extraña: <b>los pasillos cambian</b> cada vez que entro. No puedo contar casillas… ¡pero sé usar el «hasta que»! Este es mi plan:",
        box: "<ol><li>Entrar <b>fins que</b> trobi la caixa.</li><li><b>Agafar</b>-la.</li><li>Fer <b>mitja volta</b>.</li><li>Tornar <b>fins que</b> arribi a la sortida.</li><li><b>Deixar</b>-la a la casa del campament.</li></ol>|<ol><li>Entrar <b>hasta que</b> encuentre la caja.</li><li><b>Coger</b>la.</li><li>Dar <b>media vuelta</b>.</li><li>Volver <b>hasta que</b> llegue a la salida.</li><li><b>Dejar</b>la en la casa del campamento.</li></ol>" },
      { k: 'learn', ph: 'descobreix', cards: [
        { k: "El rescat|El rescate", t: "Un rescat fet de bucles|Un rescate hecho de bucles", anim: 'u7cave',
          x: "El rescat té trossos: <b>fins que</b> hi hagi la caixa, avança; agafa-la; mitja volta; <b>fins que</b> hi hagi la paret de la sortida, avança; deixa-la. Cada tros recte és un bucle amb condició, i així no importa quant fa el passadís.|El rescate tiene trozos: <b>hasta que</b> haya la caja, avanza; cógela; media vuelta; <b>hasta que</b> haya la pared de la salida, avanza; déjala. Cada trozo recto es un bucle con condición, y así no importa cuánto mide el pasillo." },
        { k: "Condició nova|Condición nueva", t: "Fins que hi hagi una caixa|Hasta que haya una caja", demo: { w: { map: ['.....', 'H>#b#', '.....'] }, prog: TP('until:box{ f } p r r until:wall{ f } d') },
          x: "La condició <b>hi ha una caixa</b> mira la casella on és en Bit. Així para just a sobre de la caixa, l'agafa, fa mitja volta amb dos girs i torna enrere fins a la casa, que és al final del passadís.|La condición <b>hay una caja</b> mira la casilla donde está Bit. Así para justo encima de la caja, la coge, da media vuelta con dos giros y vuelve atrás hasta la casa, que está al final del pasillo." },
        { k: "Projecte|Proyecto", t: "Planifica, programa i prova a cada cova|Planifica, programa y prueba en cada cueva", anim: 'plan',
          x: "Com en tots els projectes: primer el <b>pla</b> amb paraules, després els blocs, i al final <b>prova'l a totes les coves</b>. Si falla en una, fes-la <b>pas a pas</b> per trobar el bug.|Como en todos los proyectos: primero el <b>plan</b> con palabras, después los bloques, y al final <b>pruébalo en todas las cuevas</b>. Si falla en una, hazla <b>paso a paso</b> para encontrar el bug.",
          tip: "Recorda: en Bit només pot portar una caixa cada vegada i només la pot deixar en una casa.|Recuerda: Bit solo puede llevar una caja cada vez y solo la puede dejar en una casa." }
      ] },
      { k: 'seq', ph: 'mans', q: "Ordena el pla del rescat d'una caixa.|Ordena el plan del rescate de una caja.",
        items: ["Avança fins que hi hagi una caixa|Avanza hasta que haya una caja", "Agafa la caixa|Coge la caja", "Fes mitja volta|Da media vuelta", "Avança fins que hi hagi un obstacle|Avanza hasta que haya un obstáculo", "Deixa la caixa a la casa|Deja la caja en la casa"],
        ex: "Primer el pla amb paraules: ara només cal passar cada tros a blocs.|Primero el plan con palabras: ahora solo hay que pasar cada trozo a bloques." },
      { k: 'parsons', ph: 'prova', q: "Ara passa el pla a blocs. <b>Ordena'ls</b> i comprova el rescat.|Ahora pasa el plan a bloques. <b>Ordénalos</b> y comprueba el rescate.",
        w: { map: ['......', 'H>##b.', '......'] }, pool: TP('until:box{ f } p r r until:wall{ f } d'), sol: TP('until:box{ f } p r r until:wall{ f } d'),
        hint: "Primer el bucle que para a la caixa. La mitja volta són dos girs iguals.|Primero el bucle que para en la caja. La media vuelta son dos giros iguales." },
      { k: 'spot', ph: 'investiga', q: "Aquest rescat falla: en Bit es passa de la caixa i no la pot agafar. <b>Toca el bloc que s'ha de canviar.</b>|Este rescate falla: Bit se pasa de la caja y no la puede coger. <b>Toca el bloque que hay que cambiar.</b>",
        w: { map: ['......', 'H>#b##', '......'] }, prog: TPX('until:wall!{ f } p r r until:wall{ f } d'),
        ex: "El primer bucle para a l'obstacle, al final del passadís. Havia de parar quan hi hagués una caixa: «fins que hi hagi una caixa».|El primer bucle para en el obstáculo, al final del pasillo. Tenía que parar cuando hubiera una caja: «hasta que haya una caja»." },
      { k: 'build', ph: 'repte', q: "Primer rescat! Porta la caixa de cada passadís fins a la casa del campament. Els passadissos fan llargades diferents.|¡Primer rescate! Lleva la caja de cada pasillo hasta la casa del campamento. Los pasillos miden longitudes diferentes.",
        w: { map: ['.......', 'H>#b###', '.......'], alts: [['.......', 'H>####b', '.......'], ['.......', 'H>b....', '.......']] }, pal: ['fwd', 'left', 'right', 'pick', 'drop', 'until'], conds: ['box', 'wall', 'goal'],
        sol: TP('until:box{ f } p r r until:wall{ f } d'), hint: "Segueix el pla: fins a la caixa, agafa, mitja volta, fins a la paret, deixa.|Sigue el plan: hasta la caja, coge, media vuelta, hasta la pared, deja." },
      { k: 'move', ph: 'pausa', secs: 30, t: "Rescat al lloc! Fes de Bit: camina al lloc <b>fins que</b> comptis 6, ajup-te i agafa una caixa imaginària, fes <b>mitja volta</b> i torna a caminar <b>fins que</b> comptis 6. Deixa-la amb compte!|¡Rescate en el sitio! Haz de Bit: camina en el sitio <b>hasta que</b> cuentes 6, agáchate y coge una caja imaginaria, da <b>media vuelta</b> y vuelve a caminar <b>hasta que</b> cuentes 6. ¡Déjala con cuidado!" },
      { k: 'build', ph: 'repte', q: "Les estrelles de cristall! Recull-les totes i surt per la bandera. Els passadissos giren sempre cap a la dreta.|¡Las estrellas de cristal! Recógelas todas y sal por la bandera. Los pasillos giran siempre hacia la derecha.",
        w: { map: ['>#*##.', '....#.', '....#.', 'F*###.', '......'], alts: [['>####*', '.....#', '..F*##', '......', '......'], ['>##...', '..*...', '..#...', '..#...', 'F*#...']] }, pal: ['fwd', 'left', 'right', 'until', 'if', 'else'], conds: ['goal', 'wall'],
        sol: TP('until:goal{ if:wall{ r } else{ f } }'), hint: "Recordes el programa que decideix a cada pas? Fins que arribis: si hi ha obstacle, gira; si no, avança.|¿Recuerdas el programa que decide en cada paso? Hasta que llegues: si hay obstáculo, gira; si no, avanza." },
      { k: 'story', ph: 'repte', who: 'numi', title: "El truc del comptador|El truco del contador", w: { map: ['.......', '#H>##b#', '.......'] },
        t: "Ara la casa <b>no és al final del passadís</b>: si en Bit torna fins a l'obstacle, se la passa! Truc de rescatador/a: a l'anada, <b>suma 1 al comptador a cada pas</b>. A la tornada, <b>resta 1 a cada pas fins que el comptador valgui 0</b>. Llavors en Bit és just on ha començat, al costat de la casa.|Ahora la casa <b>no está al final del pasillo</b>: si Bit vuelve hasta el obstáculo, ¡se la pasa! Truco de rescatador/a: a la ida, <b>suma 1 al contador en cada paso</b>. A la vuelta, <b>resta 1 en cada paso hasta que el contador valga 0</b>. Entonces Bit está justo donde ha empezado, al lado de la casa." },
      { k: 'build', ph: 'repte', q: "Compta les passes! Porta la caixa a la casa fent servir el comptador de passes per saber quan has tornat.|¡Cuenta los pasos! Lleva la caja a la casa usando el contador de pasos para saber cuándo has vuelto.",
        w: { map: ['.......', '#H>##b#', '.......'], vname: "comptador de passes|contador de pasos", alts: [['.......', '#H>b###', '.......'], ['.......', '#H>###b', '.......']] },
        pal: ['fwd', 'left', 'right', 'pick', 'drop', 'until', 'add', 'sub'], conds: ['box', 'cnt=0', 'wall'],
        sol: TP('until:box{ f add:1 } p r r until:cnt=0{ f sub:1 } f d'),
        hint: "Anada: fins que hi hagi una caixa, Endavant i Suma 1. Tornada: fins que el comptador valgui 0, Endavant i Resta 1. I un últim pas fins a la casa.|Ida: hasta que haya una caja, Adelante y Suma 1. Vuelta: hasta que el contador valga 0, Adelante y Resta 1. Y un último paso hasta la casa." },
      { k: 'build', ph: 'repte', q: "Rescat al passadís amb revolt. El programa és gairebé bo, però a la tornada en Bit gira cap al costat equivocat. <b>Arregla'l</b>.|Rescate en el pasillo con curva. El programa es casi bueno, pero a la vuelta Bit gira hacia el lado equivocado. <b>Arréglalo</b>.",
        w: { map: ['.......', 'H>###..', '....#..', '....b..'], alts: [['.......', 'H>#####', '......#', '......b'], ['.......', 'H>#....', '..#....', '..b....']] }, pal: ['fwd', 'left', 'right', 'pick', 'drop', 'until'], conds: ['box', 'wall', 'goal'],
        prog: TP('until:wall{ f } r until:box{ f } p r r until:wall{ f } r until:wall{ f } d'), sol: TP('until:wall{ f } r until:box{ f } p r r until:wall{ f } l until:wall{ f } d'),
        hint: "A l'anada gira a la dreta per baixar. A la tornada puja i ha de girar cap a la casa: quin gir és, ara? Posa't al lloc d'en Bit.|A la ida gira a la derecha para bajar. A la vuelta sube y tiene que girar hacia la casa: ¿qué giro es, ahora? Ponte en el lugar de Bit." },
      { k: 'story', ph: 'crea', who: 'numi', title: "El projecte final|El proyecto final",
        t: "Ara el <b>projecte final</b>! Abans de posar blocs, digues el pla en veu alta: per on entra en Bit, on gira, on és la caixa i com torna. Després programa'l, prova'l a les dues coves i millora'l.|¡Ahora el <b>proyecto final</b>! Antes de poner bloques, di el plan en voz alta: por dónde entra Bit, dónde gira, dónde está la caja y cómo vuelve. Después prográmalo, pruébalo en las dos cuevas y mejóralo." },
      { k: 'create', ph: 'crea', name: "Rescat a la cova|Rescate en la cueva",
        q: "<b>Projecte final de la unitat!</b> Rescata la caixa del fons de la cova, recull les estrelles del camí i deixa la caixa a la casa del campament. El programa ha de funcionar <b>a les dues coves</b>.|<b>¡Proyecto final de la unidad!</b> Rescata la caja del fondo de la cueva, recoge las estrellas del camino y deja la caja en la casa del campamento. El programa tiene que funcionar <b>en las dos cuevas</b>.",
        crit: ["Rescata la caixa i la deixa a la casa|Rescata la caja y la deja en la casa", "Recull totes les estrelles|Recoge todas las estrellas", "Funciona a les 2 coves amb «Repeteix fins que…»|Funciona en las 2 cuevas con «Repite hasta que…»", "Extra: celebra-ho amb un llum o una nota en acabar|Extra: celébralo con una luz o una nota al terminar"],
        check: p => bitCountK(p, ['until']) >= 1 ? null : "Funciona, però el projecte demana fer servir «Repeteix fins que…».|Funciona, pero el proyecto pide usar «Repite hasta que…».",
        w: { map: ['.....b.', '.....*.', '.....#.', 'H>#*##.', '.......'], alts: [['.......', '...b...', '...#...', 'H>*#...', '.......']] },
        pal: ['fwd', 'left', 'right', 'pick', 'drop', 'until', 'if', 'else', 'light', 'note'], conds: ['box', 'wall', 'goal', 'gem', 'freeL', 'freeR'], colors: ['g', 'y', 'r', 'u'], notes: ['do', 'mi', 'sol'],
        sol: TP('until:wall{ f } l until:box{ f } p r r until:wall{ f } r until:wall{ f } d') },
      { k: 'quiz', ph: 'tanca', q: "Per què el programa del rescat funciona en coves de llargades diferents?|¿Por qué el programa del rescate funciona en cuevas de longitudes diferentes?",
        opts: ["Perquè els bucles paren quan troben la caixa o la paret|Porque los bucles paran cuando encuentran la caja o la pared", "Perquè compta les caselles abans de començar|Porque cuenta las casillas antes de empezar", "Perquè la cova sempre és igual|Porque la cueva siempre es igual"], a: 0 },
      { k: 'quiz', ph: 'tanca', q: "Quina diferència hi ha entre «Repeteix 5 vegades» i «Repeteix fins que…»?|¿Qué diferencia hay entre «Repite 5 veces» y «Repite hasta que…»?",
        opts: ["El primer repeteix un número fix de vegades; el segon, fins que es compleix una condició|El primero repite un número fijo de veces; el segundo, hasta que se cumple una condición", "Cap: fan el mateix|Ninguna: hacen lo mismo", "El segon no s'acaba mai|El segundo no se acaba nunca"], a: 0 },
      { k: 'feel', ph: 'tanca' }
    ] }
] };
